properties.query:
let kerb_events = SecurityEvent | where EventID == 4769 and ServiceName !startswith "krbtgt" and TicketEncryptionType == "0x17" | summarize kerb_time=min(TimeGenerated) by ClientUserName, ServiceName;
let service_events = SecurityEvent | where EventID == 4624 and TargetUserName endswith "$" and LogonType == 3 | summarize svc_time=min(TimeGenerated) by TargetUserName;
kerb_events | join kind=inner service_events on $left.ServiceName == $right.TargetUserName | where svc_time - kerb_time between (0min .. 120min)
